import json, os, glob, re, time, statistics, collections, pathlib
H = pathlib.Path.home()
out = {}

# --- frontmatter checks (agents + skills) ---
try:
    import yaml
except ImportError:
    yaml = None
def fm(path):
    t = open(path, encoding="utf-8", errors="replace").read()
    if not t.startswith("---"): return None, "no-frontmatter"
    parts = t.split("\n---", 1)
    if len(parts) < 2: return None, "unterminated"
    block = parts[0][3:]
    if yaml is None: return {}, "noyaml"
    try:
        d = yaml.safe_load(block)
        return (d if isinstance(d, dict) else {}), None
    except Exception as e:
        return None, "yaml-error: " + str(e).splitlines()[0][:120]
issues = []
for d in [H/".claude/agents", H/"DEV/.claude/agents"]:
    names = collections.defaultdict(list)
    for f in glob.glob(str(d/"**/*.md"), recursive=True):
        meta, err = fm(f)
        if err and err != "no-frontmatter": issues.append(("agent", f, err)); continue
        if meta and meta.get("name"):
            if not meta.get("description"): issues.append(("agent", f, "missing description"))
            names[(os.path.dirname(f), meta["name"])].append(f)
    for k, v in names.items():
        if len(v) > 1: issues.append(("agent-collision", k[1], v))
skills = {}
for d in [H/".claude/skills", H/"DEV/.claude/skills"]:
    for f in glob.glob(str(d/"*/SKILL.md")):
        meta, err = fm(f)
        name = os.path.basename(os.path.dirname(f))
        if err: issues.append(("skill", f, err))
        desc = (meta or {}).get("description", "") or ""
        skills[name] = {"path": f, "chars": len(name) + len(str(desc)), "dmi": bool((meta or {}).get("disable-model-invocation"))}
out["frontmatter_issues"] = issues
out["yaml_available"] = yaml is not None

# --- usage counters ---
cj = json.load(open(H/".claude.json"))
su = cj.get("skillUsage", {}); pu = cj.get("pluginUsage", {})

# --- transcripts ---
files = sorted(glob.glob(str(H/".claude/projects/*/*.jsonl")), key=os.path.getmtime, reverse=True)[:50]
oldest = min(os.path.getmtime(f) for f in files)
win_start = oldest
skill_hits = collections.Counter(); mcp_hits = collections.Counter(); slash_hits = collections.Counter()
hooks = collections.defaultdict(list); hook_timeouts = collections.Counter()
tool_uses = {}; denials = []
for f in files:
    for line in open(f, encoding="utf-8", errors="replace"):
        try: o = json.loads(line)
        except Exception: continue
        t = o.get("type")
        if t == "assistant":
            for c in (o.get("message", {}) or {}).get("content", []) or []:
                if isinstance(c, dict) and c.get("type") == "tool_use":
                    n = c.get("name", "")
                    tool_uses[c.get("id")] = (n, c.get("input", {}))
                    if n == "Skill": skill_hits[str((c.get("input") or {}).get("skill", ""))] += 1
                    elif n.startswith("mcp__"): mcp_hits[n.split("__")[1]] += 1
        elif t == "user":
            m = o.get("message", {}) or {}
            content = m.get("content")
            s = content if isinstance(content, str) else json.dumps(content)[:20000]
            for x in re.findall(r"<command-name>/?([^<]+)</command-name>", s): slash_hits[x.strip()] += 1
            k = o.get("toolDenialKind")
            if k and k not in ("interrupted", "cancelled") and isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get("type") == "tool_result":
                        denials.append((c.get("tool_use_id"), k))
        elif t == "attachment":
            a = o.get("attachment", {}) or {}
            if str(a.get("type", "")).startswith("hook_") and "durationMs" in a:
                key = f'{a.get("hookEvent")}|{a.get("hookName")}'
                hooks[key].append(a["durationMs"])
                if a.get("timedOut"): hook_timeouts[key] += 1
out["window"] = {"sessions": len(files), "days": round((time.time() - win_start) / 86400, 1)}

def used_in_window(ts):
    if not ts: return False
    try:
        if isinstance(ts, (int, float)): v = ts / 1000 if ts > 1e12 else ts
        else:
            from datetime import datetime
            v = datetime.fromisoformat(str(ts).replace("Z", "+00:00")).timestamp()
        return v >= win_start
    except Exception: return False

srows = []
for name, s in sorted(skills.items()):
    u = su.get(name) or {}
    hits = skill_hits[name] + slash_hits[name]
    srows.append((name, u.get("usageCount", 0), used_in_window(u.get("lastUsedAt")) or hits > 0, hits, round(s["chars"] / 4)))
out["user_skills"] = srows
out["skill_listing_est_tokens"] = sum(r[4] for r in srows)

prow = []
for k, u in sorted(pu.items()):
    plug = k.split("@")[0]
    th = sum(v for kk, v in skill_hits.items() if kk.startswith(plug + ":")) + sum(v for kk, v in slash_hits.items() if kk.startswith(plug + ":")) + sum(v for kk, v in mcp_hits.items() if kk.startswith("plugin_" + plug.replace("-", "-")))
    win = (u.get("usageCount", 0) > 0 and used_in_window(u.get("lastUsedAt"))) or th > 0
    prow.append((k, u.get("usageCount", 0), win, th))
out["plugins"] = prow
out["mcp_hits"] = dict(mcp_hits)

hk = []
for k, v in hooks.items():
    hk.append((k, len(v), int(statistics.median(v)), max(v), hook_timeouts[k]))
out["hooks"] = sorted(hk, key=lambda r: -r[2])[:15]

dc = collections.defaultdict(collections.Counter)
for tid, kind in denials:
    n, inp = tool_uses.get(tid, ("?", {}))
    if n == "Bash":
        w = str((inp or {}).get("command", "")).split()
        key = "Bash: " + " ".join(w[:2])
    else: key = n
    dc[key][kind] += 1
out["denials"] = sorted([(k, sum(v.values()), dict(v)) for k, v in dc.items()], key=lambda r: -r[1])[:15]
print(json.dumps(out, indent=0, default=str))

